import assert from "node:assert/strict";
import test from "node:test";

import { greet } from "./greet.mjs";

test("不传问候语时使用 hello", () => {
  assert.equal(greet("knit"), "hello knit");
});

test("传了问候语时使用自定义问候语", () => {
  assert.equal(greet("knit", "hi"), "hi knit");
});

